/* ---------- Permission gate ---------- */
/* the agent asks in the chat as one card: the question, the scopes to tick, and a footer with how long and the two
   answers. Without .panel it sits flat in the thread */
.pgx{position:relative;width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-1) 0;display:flex;flex-direction:column;gap:var(--dm-s-3)}
.pgx.panel{padding:var(--dm-s-4)}
.pgx-h{display:flex;gap:var(--dm-s-3);align-items:center}
.pgx-ic{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);display:grid;place-items:center;flex:none}
.pgx-ht{display:flex;flex-direction:column;min-width:0}
.pgx-ht b{font-weight:500;font-size:14px}
.pgx-ht span{font-size:13px}
/* the scopes line up with the head (owner, 18 Nov): each box centred in a 32px column under the icon tile, its words where the
   question's start, and the row's hover fill exactly the content's width, from the tile's left edge to the right edge the
   buttons below end on. The box sits 7px inside the fill, and a tag at the row's end sits 7px inside it too */
.pgx-sc{display:flex;flex-direction:column}
.pgx-o{display:grid;grid-template-columns:32px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 7px var(--dm-s-2) 0;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));cursor:pointer;font-size:13.5px;transition:background .25s}
.pgx-o>.bx{justify-self:center}
@media (hover:hover) and (pointer:fine){.pgx-o:hover{background:var(--dm-row)}}
.pgx-o input{position:absolute;opacity:0;pointer-events:none}
.pgx-o .bx{width:18px;height:18px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));box-shadow:inset 0 0 0 1.5px var(--dm-fg2);display:grid;place-items:center;color:transparent;flex:none;transition:background .3s var(--dm-ease),box-shadow .3s,color .3s}
.pgx-o .bx svg{transform:scale(.4);transition:transform .35s var(--dm-ease)}
.pgx-o input:checked+.bx{background:var(--dm-accent);box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent));color:var(--dm-on-accent)}
.pgx-o input:checked+.bx svg{transform:none}
.pgx-o input:focus-visible+.bx{outline:2px solid var(--dm-focus);outline-offset:2px}
.pgx-o .t{flex:1;min-width:0}
/* asking again for one scope, every style: nothing to tick, so the scope is a plain row led by a tile like the question's
   (what it does, in the same 32px column) and the button just says Allow (owner, 18 Nov) */
.pgx-o.one{cursor:default}
@media (hover:hover) and (pointer:fine){.pgx-o.one:hover{background:none}}
.pgx-o.one>.oi{width:32px;height:32px;display:grid;place-items:center;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2)}
:root[data-style="clean"] .pgx-o.one>.oi,:root [data-style="clean"] .pgx-o.one>.oi,:root [data-style="clean"].pgx-o.one>.oi{box-shadow:inset 0 0 0 1px var(--dm-hair)}
.pgx-o .d{display:block;font-size:12px;color:var(--dm-muted)}
.pgx-f{display:flex;align-items:center;gap:6px;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.pgx-f .sp{flex:1}
/* on a narrow stage the duration gets its own row, and the two buttons stay together under it on the right */
@container (max-width:340px){.pgx-f{flex-wrap:wrap}.pgx-f .sp{flex-basis:100%}.pgx-no{margin:var(--dm-s-2) 0 0 auto}.pgx-ok{margin-top:var(--dm-s-2)}}
/* how long: a small dropdown, the way a menu of choices usually looks */
.pgx-db{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 var(--dm-s-2) 0 10px;margin-left:0;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);white-space:nowrap;transition:background .16s,color .16s}
.pgx-db[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.pgx-db:hover{background:var(--dm-row);color:var(--dm-fg)}}
.pgx-db>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.pgx-db[aria-expanded="true"]>svg{transform:rotate(180deg)}
.pgx-pop{min-width:230px}
.pgx-ok[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
.pgx-done{display:flex;align-items:center;gap:var(--dm-s-3);padding:10px 7px 10px 0;border-radius:var(--dm-r-in);background:var(--dm-chip);font-size:13.5px}
/* its mark sits centred in the scopes' 32px column, under the head's tile, and its words start on the title's column */
.pgx-done>svg{margin-inline:8px}
/* its button is a white pill on the grey row */
.pgx-done .pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.pgx-done .pill:hover{background:var(--dm-surface);box-shadow:var(--dm-on-tint-btn-h)}}
.pgx-done .t{flex:1;color:var(--dm-fg)}
.pgx-done .t span{display:block;font-size:12px;color:var(--dm-fg2)}
.pgx-done>svg{color:var(--dm-ok)}
/* while the agent works under the permission: a neutral row with a spinner and a live line. Once done the spinner becomes the
   green tick and the row stays neutral: no green fill and no clock (owner, 18 Nov) */
.pgx-done .g{width:32px;height:18px;display:grid;place-items:center;flex:none;color:var(--dm-fg2)}
.pgx-done.ok .g{color:var(--dm-ok)}
.pgx-done .t b{display:block;font-weight:400}
/* asking again mid-run, for one more scope: the tile turns amber */
.pgx-ic{transition:background .32s var(--dm-ease)}
/* asking again keeps the tile neutral in every style: the Risky tag on the scope carries the warning (owner, 18 Nov) */
.pgx-scope{display:flex;flex-direction:column;gap:var(--dm-s-3)}
/* the line in the foot strip once you have answered (Clean only): the scopes you allowed, or that you allowed none */
.pgx-sum{display:none}

/* Clean (owner, 18 Nov): a card with the question, the scopes and an off-white foot strip. Its content sits 16px from
   every edge; the controls in the strip sit 8px from the card's edges, their round ends following its corners
   (22 = 14 + 8), and the duration select lines up with the content above by its text, not its hover box. The ticks are
   ink and draw in, the count on Allow rolls as boxes are ticked, and once you answer the scopes fold into one summary line
   in the strip while the card eases to its new height (grow(), centred in its stage). Its height is never kept */
/* the card clips its strips to its round corners; the duration menu opens out of it (nothing changes height while it is open) */
:root[data-style="clean"] .pgx.panel,:root [data-style="clean"] .pgx.panel,:root [data-style="clean"].pgx.panel{padding:16px 16px 0;overflow:clip;overflow-clip-margin:0px}
:root[data-style="clean"] .pgx.panel:has(.pgx-pop.open),:root [data-style="clean"] .pgx.panel:has(.pgx-pop.open),:root [data-style="clean"].pgx.panel:has(.pgx-pop.open){overflow:visible}
:root[data-style="clean"] .pgx-ic,:root [data-style="clean"] .pgx-ic,:root [data-style="clean"].pgx-ic{box-shadow:inset 0 0 0 1px var(--dm-hair)}
/* asking again keeps the tile neutral: the Risky tag on the scope carries the warning */
:root[data-style="clean"] .pgx-ht b,:root [data-style="clean"] .pgx-ht b,:root [data-style="clean"].pgx-ht b{line-height:20px;letter-spacing:-.01em}
:root[data-style="clean"] .pgx-ht span,:root [data-style="clean"] .pgx-ht span,:root [data-style="clean"].pgx-ht span,:root[data-style="clean"] .pgx-o .d,:root [data-style="clean"] .pgx-o .d,:root [data-style="clean"].pgx-o .d,:root[data-style="clean"] .pgx-done .t span,:root [data-style="clean"] .pgx-done .t span,:root [data-style="clean"].pgx-done .t span{line-height:18px}
:root[data-style="clean"] :is(.pgx-o,.pgx-done) .t,:root [data-style="clean"] :is(.pgx-o,.pgx-done) .t,:root [data-style="clean"]:is(.pgx-o,.pgx-done) .t{line-height:20px}
/* a scope row: its box in a 32px column under the question's tile, centred, so its words start where the question's do;
   hairlines between rows, which give way to the quiet fill of the row under the pointer */
:root[data-style="clean"] .pgx-o,:root [data-style="clean"] .pgx-o,:root [data-style="clean"].pgx-o{position:relative;display:grid;grid-template-columns:32px minmax(0,1fr) auto;column-gap:12px;transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .pgx-o>.bx,:root [data-style="clean"] .pgx-o>.bx,:root [data-style="clean"].pgx-o>.bx{justify-self:center}
:root[data-style="clean"] .pgx-o+.pgx-o,:root [data-style="clean"] .pgx-o+.pgx-o,:root [data-style="clean"].pgx-o+.pgx-o{background-image:linear-gradient(var(--dm-hair),var(--dm-hair));background-repeat:no-repeat;background-position:0 0;background-size:100% 1px}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] :is(.pgx-o:hover,.pgx-o:hover+.pgx-o),:root [data-style="clean"] :is(.pgx-o:hover,.pgx-o:hover+.pgx-o),:root [data-style="clean"]:is(.pgx-o:hover,.pgx-o:hover+.pgx-o){background-image:none}}
/* asking again for one scope: nothing to tick, so the scope is an info row, its info mark where the box would be */

:root[data-style="clean"] .pgx-o .bx,:root [data-style="clean"] .pgx-o .bx,:root [data-style="clean"].pgx-o .bx{border-radius:calc(4px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px var(--dm-fg2),var(--dm-track-ring);transition:background .2s var(--dm-ease),box-shadow .2s var(--dm-ease)}
:root[data-style="clean"] .pgx-o .bx svg,:root [data-style="clean"] .pgx-o .bx svg,:root [data-style="clean"].pgx-o .bx svg{transform:none;stroke-dasharray:21;stroke-dashoffset:21;transition:stroke-dashoffset .3s var(--dm-ease)}
:root[data-style="clean"] .pgx-o input:checked+.bx,:root [data-style="clean"] .pgx-o input:checked+.bx,:root [data-style="clean"].pgx-o input:checked+.bx{background:linear-gradient(180deg,var(--dm-btn-1),var(--dm-btn-2));box-shadow:inset 0 0 0 1px var(--dm-btn-2),inset 0 2px 3px -1px rgba(255,255,255,.28);color:var(--dm-on-btn)}
:root[data-style="clean"] .pgx-o input:checked+.bx svg,:root [data-style="clean"] .pgx-o input:checked+.bx svg,:root [data-style="clean"].pgx-o input:checked+.bx svg{stroke-dashoffset:0;transition-delay:.06s}
:root[data-style="clean"] .pgx-o:active .bx,:root [data-style="clean"] .pgx-o:active .bx,:root [data-style="clean"].pgx-o:active .bx{transform:scale(.94);transition:transform var(--dm-t-fast) var(--dm-ease)}
/* the foot strip: 8px round its 28px controls, so it is 45px tall with its hairline; the scopes end 16px above it (their
   rows keep 8px of hover room below the text). Lines are whole pixels, so the card's edge meets the strip's exactly */
:root[data-style="clean"] .pgx.panel .pgx-sc,:root [data-style="clean"] .pgx.panel .pgx-sc,:root [data-style="clean"].pgx.panel .pgx-sc{margin-bottom:-4px}
:root[data-style="clean"] .pgx.panel .pgx-f,:root [data-style="clean"] .pgx.panel .pgx-f,:root [data-style="clean"].pgx.panel .pgx-f{margin:0 -16px;padding:8px;gap:4px;border-top:1px solid var(--dm-line);background:var(--dm-strip);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .pgx-f .pgx-db,:root [data-style="clean"] .pgx-f .pgx-db,:root [data-style="clean"].pgx-f .pgx-db{padding:0 8px;margin:0;color:var(--dm-fg2);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .pgx-f :is(.pgx-db:hover,.pgx-db[aria-expanded="true"],.pill.ghost:hover),:root [data-style="clean"] .pgx-f :is(.pgx-db:hover,.pgx-db[aria-expanded="true"],.pill.ghost:hover),:root [data-style="clean"].pgx-f :is(.pgx-db:hover,.pgx-db[aria-expanded="true"],.pill.ghost:hover){background:var(--dm-hover);color:var(--dm-fg)}}
/* on a narrow stage the buttons wrap under the select: the strip's 4px gaps put them 8px under it */
@container (max-width:340px){:root[data-style="clean"] .pgx-no,:root [data-style="clean"] .pgx-no,:root [data-style="clean"].pgx-no{margin:0 0 0 auto}:root[data-style="clean"] .pgx-ok,:root [data-style="clean"] .pgx-ok,:root [data-style="clean"].pgx-ok{margin-top:0}}
/* Allow's count rolls: up as a box is ticked, down as one is cleared. No window clips it: each number moves a few pixels
   and fades, so a digit is never seen cut in half */
:root[data-style="clean"] .pgx-cnt,:root [data-style="clean"] .pgx-cnt,:root [data-style="clean"].pgx-cnt{display:inline-grid}
:root[data-style="clean"] .pgx-cnt>i,:root [data-style="clean"] .pgx-cnt>i,:root [data-style="clean"].pgx-cnt>i{grid-area:1/1;font-style:normal;font-variant-numeric:tabular-nums}
@keyframes pgxiu{from{transform:translateY(40%);opacity:0}}
@keyframes pgxou{to{transform:translateY(-40%);opacity:0}}
@keyframes pgxid{from{transform:translateY(-40%);opacity:0}}
@keyframes pgxod{to{transform:translateY(40%);opacity:0}}
/* the old number leaves first and the new one follows, so the two never sit on top of each other */
:root[data-style="clean"] .pgx-cnt>.iu,:root [data-style="clean"] .pgx-cnt>.iu,:root [data-style="clean"].pgx-cnt>.iu{animation:pgxiu .22s var(--dm-ease) .1s both}
:root[data-style="clean"] .pgx-cnt>.ou,:root [data-style="clean"] .pgx-cnt>.ou,:root [data-style="clean"].pgx-cnt>.ou{animation:pgxou .16s var(--dm-ease) both}
:root[data-style="clean"] .pgx-cnt>.id,:root [data-style="clean"] .pgx-cnt>.id,:root [data-style="clean"].pgx-cnt>.id{animation:pgxid .22s var(--dm-ease) .1s both}
:root[data-style="clean"] .pgx-cnt>.od,:root [data-style="clean"] .pgx-cnt>.od,:root [data-style="clean"].pgx-cnt>.od{animation:pgxod .16s var(--dm-ease) both}
/* answered: the result line where the scopes were (a 32px mark under the question's tile, the words under the question's
   words, the clock on the right), then the strip with the summary and Revoke or Undo in the corner */
:root[data-style="clean"] .pgx.panel .pgx-done,:root [data-style="clean"] .pgx.panel .pgx-done,:root [data-style="clean"].pgx.panel .pgx-done{display:grid;grid-template-columns:32px minmax(0,1fr) auto;grid-template-rows:auto 45px;column-gap:12px;row-gap:16px;align-items:center;padding:0;border-radius:0;background:none!important}
:root[data-style="clean"] .pgx.panel .pgx-done>:is(.g,svg),:root [data-style="clean"] .pgx.panel .pgx-done>:is(.g,svg),:root [data-style="clean"].pgx.panel .pgx-done>:is(.g,svg){grid-area:1/1}
:root[data-style="clean"] .pgx.panel .pgx-done>.t,:root [data-style="clean"] .pgx.panel .pgx-done>.t,:root [data-style="clean"].pgx.panel .pgx-done>.t{grid-area:1/2}
:root[data-style="clean"] .pgx.panel .pgx-done .t b,:root [data-style="clean"] .pgx.panel .pgx-done .t b,:root [data-style="clean"].pgx.panel .pgx-done .t b{font-weight:500}
:root[data-style="clean"] .pgx.panel .pgx-done .t b span,:root [data-style="clean"] .pgx.panel .pgx-done .t b span,:root [data-style="clean"].pgx.panel .pgx-done .t b span{font-size:inherit;line-height:inherit;color:inherit}
:root[data-style="clean"] .pgx.panel .pgx-done .t span,:root [data-style="clean"] .pgx.panel .pgx-done .t span,:root [data-style="clean"].pgx.panel .pgx-done .t span{color:var(--dm-muted)}
:root[data-style="clean"] .pgx.panel .pgx-done>.pill,:root [data-style="clean"] .pgx.panel .pgx-done>.pill,:root [data-style="clean"].pgx.panel .pgx-done>.pill{grid-area:2/3;z-index:1;align-self:end;margin:0 -8px 8px 0;color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .pgx.panel .pgx-done>.pill:hover,:root [data-style="clean"] .pgx.panel .pgx-done>.pill:hover,:root [data-style="clean"].pgx.panel .pgx-done>.pill:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .pgx.panel .pgx-done>.pill:active,:root [data-style="clean"] .pgx.panel .pgx-done>.pill:active,:root [data-style="clean"].pgx.panel .pgx-done>.pill:active{box-shadow:var(--dm-btn2-press)}
/* the strip is the summary line itself, edge to edge; Revoke or Undo sits on its right end. Its colour reaches 240px below
   the card's edge (clipped there), so while the card eases shorter no empty band shows under it */
:root[data-style="clean"] .pgx.panel .pgx-sum,:root [data-style="clean"] .pgx.panel .pgx-sum,:root [data-style="clean"].pgx.panel .pgx-sum{display:block;grid-area:2/1/3/-1;align-self:stretch;margin:0 -16px -240px;padding:8px 88px 248px 16px;border-top:1px solid var(--dm-line);background:var(--dm-strip);line-height:28px;font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
:root[data-style="clean"] .pgx-sum .s,:root [data-style="clean"] .pgx-sum .s,:root [data-style="clean"].pgx-sum .s{display:none}
@container (max-width:340px){:root[data-style="clean"] .pgx-sum .l,:root [data-style="clean"] .pgx-sum .l,:root [data-style="clean"].pgx-sum .l{display:none}:root[data-style="clean"] .pgx-sum .s,:root [data-style="clean"] .pgx-sum .s,:root [data-style="clean"].pgx-sum .s{display:inline}}
/* the mark: a neutral circle with the spinner while the agent works; done, its ring turns green and the tick draws in */
:root[data-style="clean"] .pgx.panel .pgx-done .g,:root [data-style="clean"] .pgx.panel .pgx-done .g,:root [data-style="clean"].pgx.panel .pgx-done .g{width:32px;height:32px;border-radius:50%;background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair);color:var(--dm-fg2);transition:background-color .3s var(--dm-ease),box-shadow .3s var(--dm-ease)}
:root[data-style="clean"] .pgx.panel .pgx-done.ok .g,:root [data-style="clean"] .pgx.panel .pgx-done.ok .g,:root [data-style="clean"].pgx.panel .pgx-done.ok .g{background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px var(--dm-ok-mark);color:var(--dm-ok-mark)}
:root[data-style="clean"] .pgx.panel .pgx-done.ok .g svg,:root [data-style="clean"] .pgx.panel .pgx-done.ok .g svg,:root [data-style="clean"].pgx.panel .pgx-done.ok .g svg{width:16px;height:16px;stroke-width:2;stroke-dasharray:21;animation:pgxdraw .5s var(--dm-ease) .12s both}
@keyframes pgxdraw{from{stroke-dashoffset:21}to{stroke-dashoffset:0}}
:root[data-style="clean"] .pgx.panel .pgx-done>svg,:root [data-style="clean"] .pgx.panel .pgx-done>svg,:root [data-style="clean"].pgx.panel .pgx-done>svg{width:32px;height:32px;margin:0;padding:8px;box-sizing:border-box;border-radius:50%;background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair);color:var(--dm-fg2)}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] :is(.pgx-o .bx,.pgx-o .bx svg,.pgx-done .g),:root [data-style="clean"] :is(.pgx-o .bx,.pgx-o .bx svg,.pgx-done .g),:root [data-style="clean"]:is(.pgx-o .bx,.pgx-o .bx svg,.pgx-done .g){transition:none}:root[data-style="clean"] :is(.pgx-cnt>i,.pgx-done.ok .g svg),:root [data-style="clean"] :is(.pgx-cnt>i,.pgx-done.ok .g svg),:root [data-style="clean"]:is(.pgx-cnt>i,.pgx-done.ok .g svg){animation:none}}

DM.def('permission-gate', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{figma}', I('figma')).replace(/\{chk\}/g, I('check','xs')).replace('{chev}', I('chev-d','xs'));
  const root = $('.pgx', r), ok = $('.pgx-ok', r), no = $('.pgx-no', r), sc = $('.pgx-sc', r), title = $('.pgx-ht b', r), sub = $('.pgx-ht .muted', r);
  const first = { sc:sc.innerHTML, title:title.textContent, sub:sub.textContent, no:no.textContent };
  const boxes = () => $$('.pgx-o input', sc);
  // the card fits what it holds at every moment, in every style (grow(), never a kept height: owner, 17 and 18 Nov). Clean
  // (owner, 18 Nov) has its own touches:
  // the count on Allow rolls, the answer gets a summary line in the foot strip, and the done mark is a tick that draws.
  // Soft and Blueprint keep theirs
  const ds = r.closest('[data-style]'), clean = !!ds && ds.dataset.style === 'clean';
  // grow() starts once the card's entrance (which scales it from .98) has ended, so it measures the card at its real size
  Promise.resolve().then(() => Promise.all(root.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && root.isConnected) c.offs.push(grow(root)); });
  // where a result row goes: in the card, or in grow()'s wrapper inside it
  const into = () => $(':scope>.dm-grow', root) || root;
  // how long: This task, Today or Always, from the dropdown in the footer
  let dur = 'This task';
  const span = () => dur === 'Always' ? 'always' : 'for ' + dur.toLowerCase();
  const word = n => n > 1 ? 'scopes' : 'scope';
  // Clean's Allow: its number in a window of its own, so a new count rolls in (up as a box is ticked, down as one clears)
  const label = n => n ? `<span class="pgx-l">Allow <span class="pgx-cnt"><i>${n}</i></span> <span class="pgx-w">${word(n)}</span></span>` : 'Pick a scope';
  let shown = 0;
  const roll = (cnt, n, up) => { const old = cnt.lastElementChild, nu = document.createElement('i'); nu.textContent = n; nu.className = up ? 'iu' : 'id'; if (old){ old.className = up ? 'ou' : 'od'; setTimeout(() => old.remove(), REDUCE ? 0 : 300); } cnt.appendChild(nu); };
  // Clean asks again for its one scope as a plain row (nothing to tick), and its button just says Allow
  const one = () => $('.pgx-o.one', sc);
